# MATLAB Program: Ultrasound Signal Analysis (Time Domain to Frequency Domain)

```matlab
% =========================================================================
% Ultrasound Signal Converter: Voltage vs Time to Magnitude(dB) vs Frequency(MHz)
% =========================================================================

function [freq_MHz, magnitude_dB] = ultrasound_fft_analysis(time, voltage, varargin)
% ULTRASOUND_FFT_ANALYSIS Convert ultrasound time-domain signal to frequency domain
%
% Inputs:
%   time    - Time vector (in seconds or microseconds)
%   voltage - Voltage amplitude vector
%   varargin - Optional parameters:
%              'TimeUnit' - 's' (seconds) or 'us' (microseconds), default: 's'
%              'Window' - Window function ('hanning', 'hamming', 'blackman', 'none'), default: 'hanning'
%              'PlotResults' - true/false, default: true
%
% Outputs:
%   freq_MHz     - Frequency vector in MHz
%   magnitude_dB - Magnitude in dB

    % Parse optional inputs
    p = inputParser;
    addParameter(p, 'TimeUnit', 's', @ischar);
    addParameter(p, 'Window', 'hanning', @ischar);
    addParameter(p, 'PlotResults', true, @islogical);
    parse(p, varargin{:});

    % Convert time to seconds if needed
    if strcmp(p.Results.TimeUnit, 'us')
        time = time * 1e-6; % Convert microseconds to seconds
    end

    % Ensure column vectors
    time = time(:);
    voltage = voltage(:);

    % Calculate sampling parameters
    N = length(voltage);
    dt = mean(diff(time)); % Sampling period
    Fs = 1/dt;             % Sampling frequency

    fprintf('=== Signal Parameters ===\n');
    fprintf('Number of samples: %d\n', N);
    fprintf('Sampling frequency: %.2f MHz\n', Fs/1e6);
    fprintf('Time duration: %.2f µs\n', (N-1)*dt*1e6);
    fprintf('Frequency resolution: %.3f kHz\n', Fs/N/1e3);
    fprintf('========================\n\n');

    % Apply window function
    switch lower(p.Results.Window)
        case 'hanning'
            window = hanning(N);
            fprintf('Applied Hanning window\n');
        case 'hamming'
            window = hamming(N);
            fprintf('Applied Hamming window\n');
        case 'blackman'
            window = blackman(N);
            fprintf('Applied Blackman window\n');
        case 'none'
            window = ones(N, 1);
            fprintf('No window applied\n');
        otherwise
            window = hanning(N);
            fprintf('Unknown window type. Applied Hanning window\n');
    end

    voltage_windowed = voltage .* window;

    % Perform FFT
    Y = fft(voltage_windowed);

    % Calculate two-sided spectrum
    P2 = abs(Y/N);

    % Calculate one-sided spectrum (positive frequencies only)
    P1 = P2(1:floor(N/2)+1);
    P1(2:end-1) = 2*P1(2:end-1);

    % Convert to dB (with reference to maximum or 1V)
    % Using reference to maximum value
    magnitude_dB = 20*log10(P1/max(P1));

    % Alternative: Use 1V as reference
    % magnitude_dB = 20*log10(P1);

    % Create frequency vector in MHz
    freq = Fs*(0:floor(N/2))/N;
    freq_MHz = freq / 1e6;

    % Plot results if requested
    if p.Results.PlotResults
        figure('Position', [100, 100, 1200, 800]);

        % Time domain plot
        subplot(2,1,1);
        plot(time*1e6, voltage, 'b', 'LineWidth', 1.5);
        hold on;
        plot(time*1e6, voltage_windowed, 'r--', 'LineWidth', 1);
        grid on;
        xlabel('Time (µs)', 'FontSize', 12);
        ylabel('Voltage (V)', 'FontSize', 12);
        title('Time Domain Signal', 'FontSize', 14, 'FontWeight', 'bold');
        legend('Original Signal', 'Windowed Signal');
        xlim([min(time*1e6), max(time*1e6)]);

        % Frequency domain plot
        subplot(2,1,2);
        plot(freq_MHz, magnitude_dB, 'b', 'LineWidth', 1.5);
        grid on;
        xlabel('Frequency (MHz)', 'FontSize', 12);
        ylabel('Magnitude (dB)', 'FontSize', 12);
        title('Frequency Domain Spectrum', 'FontSize', 14, 'FontWeight', 'bold');
        xlim([0, max(freq_MHz)]);
        ylim([min(magnitude_dB), 0]);

        % Add -3dB and -6dB lines
        hold on;
        yline(-3, 'r--', '-3dB', 'LineWidth', 1.5, 'LabelHorizontalAlignment', 'left');
        yline(-6, 'g--', '-6dB', 'LineWidth', 1.5, 'LabelHorizontalAlignment', 'left');

        % Find and display peak frequency
        [~, idx_peak] = max(magnitude_dB);
        peak_freq = freq_MHz(idx_peak);
        plot(peak_freq, magnitude_dB(idx_peak), 'ro', 'MarkerSize', 10, 'LineWidth', 2);
        text(peak_freq, magnitude_dB(idx_peak)+2, sprintf('Peak: %.2f MHz', peak_freq), ...
            'HorizontalAlignment', 'center', 'FontSize', 10, 'FontWeight', 'bold');

        fprintf('Peak frequency: %.2f MHz\n', peak_freq);
    end
end

%% ========================================================================
% EXAMPLE USAGE SCRIPT
% ========================================================================

%% Example 1: Simulated ultrasound signal
clear all; close all; clc;

% Simulation parameters
Fs = 100e6;              % Sampling frequency: 100 MHz
duration = 10e-6;        % Duration: 10 microseconds
t = 0:1/Fs:duration-1/Fs; % Time vector

% Create a simulated ultrasound pulse (5 MHz center frequency)
f0 = 5e6;                % Center frequency: 5 MHz
pulse_cycles = 3;        % Number of cycles
pulse_duration = pulse_cycles/f0;

% Gaussian-modulated sinusoid (ultrasound pulse)
voltage = exp(-((t-pulse_duration).^2)/(2*(pulse_duration/4)^2)) .* sin(2*pi*f0*t);

% Add some noise
voltage = voltage + 0.05*randn(size(voltage));

% Perform FFT analysis
[freq_MHz, magnitude_dB] = ultrasound_fft_analysis(t, voltage, ...
    'TimeUnit', 's', ...
    'Window', 'hanning', ...
    'PlotResults', true);

%% Example 2: Load from file (uncomment and modify as needed)
% % Load your data file
% data = load('ultrasound_data.txt'); % or use readmatrix, csvread, etc.
% time = data(:, 1);      % First column: time
% voltage = data(:, 2);   % Second column: voltage
% 
% % Analyze
% [freq_MHz, magnitude_dB] = ultrasound_fft_analysis(time, voltage, ...
%     'TimeUnit', 'us', ...  % Specify if time is in microseconds
%     'Window', 'hanning', ...
%     'PlotResults', true);

%% Example 3: Calculate bandwidth
[freq_MHz, magnitude_dB] = ultrasound_fft_analysis(t, voltage, ...
    'PlotResults', false);

% Find -6dB bandwidth
idx_6dB = find(magnitude_dB >= -6);
if ~isempty(idx_6dB)
    bandwidth_6dB = freq_MHz(idx_6dB(end)) - freq_MHz(idx_6dB(1));
    center_freq = mean([freq_MHz(idx_6dB(end)), freq_MHz(idx_6dB(1))]);
    fprintf('\n-6dB Bandwidth: %.2f MHz\n', bandwidth_6dB);
    fprintf('Center Frequency: %.2f MHz\n', center_freq);
    fprintf('Fractional Bandwidth: %.1f%%\n', (bandwidth_6dB/center_freq)*100);
end

%% ========================================================================
% SIMPLE STANDALONE VERSION (Copy-paste ready)
% ========================================================================

function simple_ultrasound_fft(time, voltage)
    % Simple version without optional parameters

    N = length(voltage);
    dt = mean(diff(time));
    Fs = 1/dt;

    % Apply Hanning window
    voltage_windowed = voltage(:) .* hanning(N);

    % FFT
    Y = fft(voltage_windowed);
    P2 = abs(Y/N);
    P1 = P2(1:floor(N/2)+1);
    P1(2:end-1) = 2*P1(2:end-1);

    % Convert to dB
    magnitude_dB = 20*log10(P1/max(P1));

    % Frequency in MHz
    freq_MHz = Fs*(0:floor(N/2))/N / 1e6;

    % Plot
    figure;
    subplot(2,1,1);
    plot(time*1e6, voltage);
    xlabel('Time (µs)'); ylabel('Voltage (V)');
    title('Time Domain');
    grid on;

    subplot(2,1,2);
    plot(freq_MHz, magnitude_dB);
    xlabel('Frequency (MHz)'); ylabel('Magnitude (dB)');
    title('Frequency Domain');
    grid on;
end
```

## Key Features:

1. **Flexible input handling** - Supports time in seconds or microseconds
2. **Window functions** - Hanning, Hamming, Blackman, or none
3. **Proper FFT scaling** - Correctly normalized one-sided spectrum
4. **dB conversion** - Magnitude in decibels (referenced to maximum)
5. **Visualization** - Automatic plotting with peak detection
6. **Bandwidth calculation** - Example code for -6dB bandwidth
7. **Simple version** - Standalone function for quick use

## Usage:
```matlab
[freq_MHz, mag_dB] = ultrasound_fft_analysis(time_vector, voltage_vector);
```

Save this as `ultrasound_fft_analysis.m` and run the examples!

